quests[48937] = { id = 48937, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Create Netherwalker's Portal Generator" }
quests[48939] = { id = 48939, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Show Me What You've Got", description = "It looks like you understand the basics. Now it's time to put everything together.\n\nHead for the ring. Once you hear the starting pistol, you will have one minute to score as high as possible.\n\nGnolls are worth one point. Run 'em through with the harpoon!\n\nIf you see a paper zeppelin, bag it with your bolas for fifty points!\n\nLeaping fences gives you style. Style gives you more points when you skewer gnolls or down zeppelins. It's super important, so don't forget to keep jumping fences!", progress = "Kul Tiran riding is a true show of mastery and sport!", completion = "What a showing!", objectives = "Mount Cooper to begin your show and score at least 150 points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48940] = { id = 48940, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "West Trebuchet Defended" }
quests[48941] = { id = 48941, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Slight Detour", description = "If this coven is drawing its power from these ancient ruins, then I may just know of something that could help us fight back.\n\nMeet me at the first fork along the Highroad Pass. There is something there I want you to see.", completion = "Good, you are here.\n\nUnfortunately it looks like we're not going to have an easy path to our destination.", objectives = "Meet with Lucille Waycrest at Highroad Pass in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48942] = { id = 48942, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Yeti to Rumble", description = "It would seem that the guard have been lax in patrolling the Highroad Pass. The mountain yetis have taken advantage of their absence, and now lie directly in our path.\n\nI am no soldier, {class}, so I will need to ask that you take care of them while I try to sneak past.  If we can drive them off the road, at least it will make the pass safe again for travelers.", progress = "We should drive the yetis back from the road. Having a major trade route cut off by monsters isn't going to help our fight against the coven.", completion = "Thank you, {class}. Keeping the pass clear will ensure a steady stream of supplies to Highroad Gate.\n\nWe will need them in the battles to come.", objectives = "Kill 8 Chillfur Yetis in Alpine Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48943] = { id = 48943, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Salvage Rights", description = "This poor trader was set upon by the yetis.  There's nothing we can do for him now, but we would be remiss to let his supplies be laid to waste by these brutes.\n\nSee if you can find any supplies worth salvaging. You can use Bella as a pack horse.\n\nDon't worry, she's a brave mare. She won't spook easily.", progress = "Have you found anything salvageable?", completion = "I'm impressed. I didn't think there would be this much left from his shipment. This will be very helpful to our men at the gate.\n\nBella knows the way, so she should be able to get these to them.  This place is too dangerous to keep her hitched up, anyway.", objectives = "Recover the Wrapped Supplies, Cask of Salted Fish, Hardened Lockbox, and Bucket of Grain from Alpine Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48944] = { id = 48944, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unlocking History", description = "I'm sure you're wondering why I've brought you here.  \n\nLocated somewhere inside this cottage is a hidden door. If we can find a way to access it, the answer to your questions, and possibly our survival against the coven, should lie beyond.\n\nHelp me search for it, {class}.", progress = "The opening must be here somewhere...", completion = "You found it! I knew that they were more than stories!\n\nCome, let us see what's inside.", objectives = "Find the secret passageway in the Forgotten Lodge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48945] = { id = 48945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Ruins of Gol Var", description = "What lies beyond are more ruins, much like those the coven sought.  \n\nHowever, these ruins served a different purpose, one that established the legacy of House Waycrest thousands of years ago.\n\nLet us head inside, and I will explain.", progress = "Just a little further...", completion = "Who would've thought that from this stuffy little chamber would rise some of the greatest warriors of House Waycrest's history?\n\nAre you prepared to follow in their footsteps?", objectives = "Escort Lucille Waycrest into Gol Var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48946] = { id = 48946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Order of Embers", description = "The Order of Embers was the name given to those who took up these arms against the Drust. Using the tools and methods uncovered by the scholars, they were able to counter the Drust's magic, and ensure our victory in the war.\n\nIf the coven wants to use the Drust's magic against us, then we'll use the order's weapons against them.\n\nThe knowledge of the order rests here, but without a hand to wield it, it will do us no good. \n\nWill you be that hand, {class}? Will you revive the Order of Embers?", progress = "What say you?", completion = "You do great honor to my family, {class}.  The most noble of Waycrests were once inquisitors of the order.\n\nIt is only fitting that it is you who takes up its mantle now.", objectives = "Take the Tome of Silver and Ash in Gol Var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48947] = { id = 48947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gol Koval", description = "A group of hunters went up into the hills awhile ago and we haven't heard back from them. \n\nMy niece is up there and it isn't like her to be out of touch for so long! Would you please find her?\n\nShe was headed towards Gol Koval.", completion = "My aunt sent you? Oh, Light bless that woman.", objectives = "Find Rebecca Hale in Gol Koval.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48948] = { id = 48948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The North Pass Caverns", description = "Please, you must help!\n\nMy grandson got lost around the caves to the north, and I'm so afraid that the troggs might have got him!  \n\nMy husband went after him, but he's getting on in years, and I fear he imagines himself tougher than he really is.\n\nCould you help them? You should be able to catch up with Thaddeus along the northern road.", completion = "I'm not lost! My grandson and his friends ran off and I've been looking for them. I wanted to find them before the troggs did!", objectives = "Find Thaddeus Rifthold near the North Pass Caverns.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48949] = { id = 48949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weeds of the Mire", description = "<Magura weakly opens her eyes as you approach.>\n\nHelp me... weak... can't heal...\n\n<Magura struggles to raise an arm to point towards a nearby plant.>\n\nGraveweed... help... more... please...", objectives = "Collect 6 sprigs of Graveweed from the Dreadmire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48951] = { id = 48951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: Voidmaw" }
quests[48952] = { id = 48952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Throw Them a Bone" }
quests[48953] = { id = 48953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: Darkcaller" }
quests[48954] = { id = 48954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of a Titan", description = "<Before your eyes, a trickle of blood from the fallen titan Argus congeals into a flawless gemstone. Holding it in your palm, you sense an almost unfathomable power emanating from within... along with echoes of pain and sorrow.\n\nIt is the last remnant of a battle that should not have been winnable. An impossible achievement. Yet, as with all victories, this one came at tremendous cost.\n\nYou realize immediately to whom you must convey this prize.>", completion = "Champion, you have returned... and not a moment too soon.\n\nThe object you hold in your hands is but one of many mysteries unfolding before us.", objectives = "Bring the blood of Argus the Unmaker to Khadgar in Dalaran.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48957] = { id = 48957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: Void-Blade Zedaat" }
quests[48958] = { id = 48958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Interruption" }
quests[48959] = { id = 48959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: Dark Fissures" }
quests[48962] = { id = 48962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Telogrus Rift", description = "Umbric and his blood elves were cast out of their home for their pursuit of understanding.\n\nI know the dangers of the void better than most. We should lend them our aid and ensure they don't do anything too foolhardy.\n\nThis rift will take us to their current location. I hope we are not too late to help them.", completion = "Former blood elves willing to pledge to our cause. This is better than I dared hope.", objectives = "Travel to Telogrus Rift and complete the scenario.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48963] = { id = 48963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Diversionary Tactics", description = "Our destination is that cottage up ahead. I know it doesn't look like much, but a great deal of history is hidden inside.\n\nFirst, though, we'll need to deal with that massive yeti camped just outside. I'd hate to ask it of you, but I'll need you to draw his attention so I can slip inside.\n\nOnce you've taken care of him, I'll meet you within.", progress = "I'll meet you inside, {class}.", completion = "That was close! \n\nI'm glad to have such a capable {class} as my guardian. I would hate to be your enemy.", objectives = "Defeat Frostmange in Alpine Rise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48964] = { id = 48964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Immortal Ace", description = "<The scroll's runes shift to a more intelligible form.>\n\nAn effigy. The Many-Faced One requires it.\n\nSteal from the Imps. Steal from the Fiends. Steal from the Ur'zul.\n\nHe comes.", objectives = "Collect bones from the Antoran Wastes to form a bone effigy.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48965] = { id = 48965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Settle the Score", description = "A year ago I lost my daughter to the largest boar in the forest.\n\nI have tracked him since, trading blows back and forth. But this time...\n\nLet's just say I don't have much time left.\n\nAll I wish for is vengeance. Please {class}, avenge us so that my soul can leave this plane and join my daughter, wherever she may be.", progress = "Though my lifeblood drains, all I yearn for is vengeance.", completion = "<Caleb's body is lifeless, still warm. His wounds claimed him while you were gone.\n\nHis face seems content, as though he knew you would finish the job.>", objectives = "Kill Chartusk in Foxhollow Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48973] = { id = 48973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of Argussian Reach", description = "Your allies among the Argussian Reach have requested your presence. They wish to reward you for your continued efforts on their behalf.", completion = "Greetings, {name}.\n\nLong have we awaited this day. Argus was all but lost, its true denizens forced to remain hidden lest we perish. Your efforts on our behalf have allowed us to once again live free from fear. Please accept these trophies as a symbol of our gratitude.", objectives = "Speak with Toraan the Revered on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48974] = { id = 48974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Paragon of the Army of the Light", description = "Your allies in the Army of the Light would like to thank you for your continued support. They await you on the Vindicaar.", completion = "Krona ki cristorr, champion!\n\nYour presence among the Army of the Light has been a singular boon to our cause. Gratitude is not all that we may offer. Please accept these trophies as a tribute to your unwavering support.\n\nTogether we will bring about the Legion's end.", objectives = "Speak with Vindicator Jaelaana on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48976] = { id = 48976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Argussian Reach", description = "{class}t, thanks to your efforts, our forces have been able to locate resources and prevent them from falling into the Legion's hands.\n\nWith your continued assistance, we will be able to provide additional resources.", completion = "Highlord, thanks to your efforts, our forces have been able to secure additional resources from the battlefield.\n\nThe more you continue to dominate the battlefield the more resources our forces can spare.", objectives = "Speak with Toraan the Revered on the Vindicaar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48977] = { id = 48977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supplies From the Army of the Light", description = "Archenon poros, champion.\n\nThe Army of the Light wishes to thank you for your aid against the Legion's forces on Argus.\n\nPlease accept these supplies with our gratitude. Your continued support brings us ever closer to our ultimate goal of eradicating the Legion once and for all.", completion = "Archenon poros, champion.\n\nThe Army of the Light wishes to thank you for your aid against the Legion's forces on Argus.\n\nPlease accept these supplies with our gratitude. Your continued support brings us ever closer to our ultimate goal of eradicating the Legion once and for all.", objectives = "Speak with Vindicator Jaelaana on the Vindicaar for your reward.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48982] = { id = 48982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion Point: Aurinor" }
quests[48983] = { id = 48983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mining Regulation" }
quests[48985] = { id = 48985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seat of the Triumvirate: Twilight-Harbinger Tharuul" }
quests[48986] = { id = 48986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Take the High Road", description = "Let us continue to Arom's Stand.  It will take some time to parse the knowledge of the tome and train more inquisitors for our cause.\n\nIf the order's weapons are as effective against the coven as they were against the Drust, we may stand a chance of rescuing my family and restoring this land to its former glory.\n\nI will make my way there on foot. Until we meet again, {class}.", completion = "I'm glad you made it, {name}. \n\nWe'll need to get started right away if we want to use the knowledge in this tome to fight the coven.", objectives = "Meet with Lucille Waycrest at Arom's Stand in Drustvar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48987] = { id = 48987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Valley of Sorrows", description = "Your friend's memories are gone. \n\nDat is Akunda's gift to us. He takes away our painful memories, but a lot more than dat has gone missing lately. \n\nI can't even remember what I had for breakfast, and it's getting worse by de day. \n\nSomething's not right. \n\nMeijani and I had a plan. We were going to do... something... in de Valley of Sorrows. It's where Akunda keeps de forgotten memories. \n\nIf you're looking for answers, finding Meijani is de best place to start.", completion = "Who are you? Have we met before?", objectives = "Find Meijani in the Valley of Sorrows.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48988] = { id = 48988, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Memory Breach", description = "De memories of Akunda's followers rest within dis valley. \n\nMost are best left forgotten, but dey may be our only chance to find out what happened to Akunda. \n\nLook back upon de memories here. See if you can find any clues about what happened to our loa. \n\nBe warned. Dis task is not for de weak. What you witness in dese memories can't be unseen.", progress = "Peer into de memories. See what you can find.", completion = "It is as I feared. De loa's own memories have been taken from him.", objectives = "Look for clues within Unwanted Memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48991] = { id = 48991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vile Infestation", description = "Redemption must be earned. \n\nWe do good works to show Akunda we are worthy of his blessing. \n\nDe ranishu are a plague upon these lands. Dey devour everything in sight, with no regard for taste or texture. \n\nIf dey go unchecked, those vile pests will eat their way straight to de temple.\n\nRid de mesa of their presence. Show Akunda you are worthy of his gift.", completion = "Akunda smiles upon you. He knows what you have done here today.", objectives = "Slay 12 ranishu in Redrock Mesa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48992] = { id = 48992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sacred Remains", description = "Dis area was once a lush jungle, home to many great and powerful thunder lizards.\n\nDe bones of those ancient and powerful creatures are still buried around de temple.\n\nGreat power lingers within those ancient remains... you will need such power to call upon Akunda.\n\nSearch de area and return to me with de ancient bones of de thunder lizards.", progress = "Have you found de ancient bones?", completion = "Dese bones still resonate with power.", objectives = "Collect 6 Sacred Remains.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48993] = { id = 48993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powerful Conductors", description = "Akunda offers us a chance to start anew. \n\nThrough a sacred ritual, de loa enters our mind and removes de memories dat cause us pain. \n\nIf you seek Akunda's blessing, den you must first prepare for de ritual. \n\nDe pests dat feed on de wildlife here have antennae dat are great conductors for magic. De larger, de better. \n\nTheir leader's antennae should do de trick. He's easily three times de size of de normal ranishu.", progress = "Do you have de antennae?", completion = "Yes... dis will work well.", objectives = "Retrieve Rorgog's Antennae.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[48996] = { id = 48996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ending the Madness", description = "Akunda the Exalted is not who he seems. \n\nHe poisoned the eternal spring, sickening all who drank from it. Even I was not immune to his abhorrent alchemy.  \n\nNow he drains my power, abusing my gift to wipe the minds of all who might try to stop him. \n\nWe will not let him succeed. \n\nWhat little power I have left, I will lend to you. \n\nUse it to call the storm and end the madness that has taken over my temple.", completion = "You wield my gift well, {name}. \n\nNow that my power has returned, I can heal the minds of my children.", objectives = "Defeat Akunda the Exalted.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49001] = { id = 49001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inconvenient Spirits", progress = "I've never met a spirit that made my day better.", completion = "Well, you're good at killing. I could tell that even from back here. Welcome to the crew.", objectives = "Kill 8 Tortured Spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49002] = { id = 49002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forced Grounding", description = "<This is one of the spears that Faithless trappers use to pull pterrordaxes to the ground. It has a long chain attached to its base.\n\nWith good aim, you could use it to pull a Faithless pterrordax rider to the ground so you could fight them.>", progress = "<Rakjan lifts his head proudly.>", completion = "<Rakjan nods in approval. That's one less Fangcaller to worry about.>", objectives = "Use the Faithless Trapper's Spear to pull Fangcaller Hrillik's pterrordax down from the sky above you, and kill him.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49003] = { id = 49003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance From Above", description = "Emperor Korthek hides deep in his stolen temple below ground. We must create such chaos that he has no choice but to emerge to face us.\n\nThe vulpera riot is a good start, but it will not be enough. Alone, they are no match for the Faithless army.\n\nThankfully, they are not alone.\n\nWe will ride the mighty Rakjan through the skies. While you throw lightning bombs, I'll use my charged staff to blast the Faithless armies below.\n\nLet us hope that is enough to lure out Korthek. I am eager to finish this.", completion = "Emperor Korthek is certainly on his way to us by now. We must prepare quickly.", objectives = "Ride Rakjan the Unbroken and kill Faithless.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49005] = { id = 49005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattered and Broken", description = "Something is terribly wrong.\n\nUnwanted memories have been released from their magical confines. \n\nAkunda's power is supposed to keep dem sealed away...\n\nDe physical manifestation of our most haunting memories have no place in dis world. \n\nDey must be destroyed.", completion = "You did what was right. Memories like those have no place in dis world.", objectives = "Kill Fractured and Distorted Memories.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49007] = { id = 49007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Commander on Deck!", description = "<The device hums to life, ready to provide you with access to Squadron Commander Vishax's portal in the Antoran Wastes.>", objectives = "Use Vishax's Portal.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49013] = { id = 49013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Jolt of Power", description = "I have you to thank for removing that usurper. \n\nMy strength is returning, unfortunately, the damage to my children has already been done. \n\nThey are weak and dying. I need you to restore them.\n\nMy blessing will give you power over the storms. \n\nUse it to save my children, as you have saved me.", objectives = "Use the Blessing of Akunda to revive Stormhide Lizards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49014] = { id = 49014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Burning Throne", description = "The time has come, {name}, to begin our assault upon Antorus. Everything we have fought for, everything our friends and family have sacrificed, has brought us to this moment.\n\nWe will fire Light's Judgment upon the walls of the accursed citadel and storm their seat of power. We will end the Legion.\n\nAfter all you have done, it is fitting that you have the honor. Speak to Romuul and let us finish our mission.", completion = "After so many years... so many sacrifices... victory is finally within our grasp.", objectives = "Speak with Grand Artificer Romuul while above the Antoran Wastes to open the way to Antorus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49015] = { id = 49015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, the Burning Throne: The Death of a Titan", description = "There is no way to express the depth of my sorrow. My rage. What Sargeras has done...\n\nArgus, my home world, holds the soul of a titan. It has been twisted and corrupted beyond redemption, its power harnessed to fuel the Legion's infinite army.\n\nWe must do the impossible... breach the depths of Antorus and sever the Legion's connection to the world soul.\n\nPlease, {name}. End its pain, its suffering. In striking down the dark heart of Argus, we will defeat the Legion... and redeem the soul of my world.", progress = "Argus... what could have been...", completion = "It is finished. At long last, the Burning Crusade is over.\n\nI thank you for all you did, {name}. With the power of Argus feeding his Dark Pantheon, Sargeras would have been unstoppable.\n\nOn behalf of the draenei, the eredar, the countless worlds destroyed by the Legion...\n\nThank you.", objectives = "Strike down the soul of Argus in Antorus, the Burning Throne.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49027] = { id = 49027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Targets of Opportunity: Terminus", description = "Those Legion ships are a problem, {name}.\n\nEven now they dock perilously close to the Vindicaar, threatening us with their presence.\n\nSometimes when fighting the Legion it is better to go straight to the top rather than thinning their numbers.\n\nGo to the shipyards of Terminus and slay their officers and commanders. That should rattle their forces and put them back on the defensive.You will be able to choose one of these rewards:" }
quests[49028] = { id = 49028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sweater for Rupert", description = "The nights are cold in this area, and I am worried my poor dog will freeze to death. I wish to sew him a sweater, but I have no materials to make one with.\n\nI would pay anyone who brings me a pair of porcupine quills and four raccoon tails.\n\n-Kolta", progress = "Is there something you need from me?", completion = "Thank you, my dog and I are eternally grateful.", objectives = "Collect Kolta's materials.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49029] = { id = 49029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Invasion of Space", description = "We are on the Legion home world, but we must not let ourselves get caught unawares.\n\nThese invasion points can bolster their forces and ruin our plans. By defeating them on their territory we also damage their command and infrastructure.\n\nSlay the commanders and stop their invading forces. The fight to push the Legion back begins now!You will be able to choose one of these rewards:" }
quests[49030] = { id = 49030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Abyss", description = "Our scouts have delivered a disturbing report, champion.\n\nSome of the more powerful creatures of the Void are carrying powerful crystals that augment their abilities. They now pose a greater threat than before, and we can no longer ignore them.\n\nFind these void-tainted monstrosities and take their crystals. We will find a way to dispose of them safely.You will be able to choose one of these rewards:" }
quests[49031] = { id = 49031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out With The Inquisitors", description = "Of all of the demons at the Legion's disposal, the inquisitors are some of the most terrible.\n\nEven feared by some of the lesser demons, these monsters delight in cruelty and torturing their captives.\n\nInquisitors revel in the terror they cause, but perhaps we can make that work to our advantage.\n\nFind the most powerful inquisitors you can and defeat them. Their deaths will not only improve the morale of our troops, but also send a message to their lesser forces.You will be able to choose one of these rewards:" }
quests[49032] = { id = 49032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Antorus, the Burning Throne: Dark Passage", description = "Despite the dangerous energies pulsing out from the heart of Argus, the Soulhunter travels unhindered through the Burning Throne. Our scouts report that his vessel harnesses the power of demonic runes to safely reach the Hallowed Felworks.\n\nIf we obtain those runes, it would allow the Vindicaar to follow the same route. This could save our forces valuable time.", progress = "Without the runes, we must face Sargeras' army head on.", completion = "Magnificent work!\n\nOnce these runes are integrated into our shielding matrix, the Vindicaar will be able to bypass the Burning Throne's defenses and strike directly at the felworks.", objectives = "Collect 4 Runes of Passage from Imonar the Soulhunter in Antorus, the Burning Throne on Normal Difficulty.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49033] = { id = 49033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE ME" }
quests[49036] = { id = 49036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Best In Show", description = "Now that the troggs have been taken care of, let's get on with the real show!\n\nYou've more than proven yourself as a capable rider - ready to get back in the ring and go big?\n\nSee if you can beat three hundred points!", progress = "Some people say you cannot simply ride the horse - you must BECOME the horse.\n\nThat's poppycock. Just ride the horse.", completion = "What a showing!", objectives = "Mount Cooper to begin your show and score at least 300 points.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49039] = { id = 49039, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Start of a Monster Hunt", description = "This is the closest I've been to a dead body, how exciting! What do you think murdered him?\n\nRegardless, it is my duty to ensure the safety of individuals under my employ. With a combination of my wit and bravery, and your practical skills, we should be able to track it down.\n\nThis will be a tale for the ages!\n\nLet's start with looking around the camp, see if you can find any clues.", progress = "Did you find anything? I'm still caught up in examining this poor fellow.", completion = "A trail, you say? I wonder where it leads...", objectives = "Investigate the camp wreckage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49040] = { id = 49040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fond Farewells", description = "Dis is where we part ways, {name}.\n\nI'm going to take de name Akunda, and start a new life here. \n\nWhen you find Rakera, and I know you will, give her my thanks. \n\nShe saved my life, and I'm going to make sure to live a life dat was worth saving. \n\nIf you find yourself back in de city, could you deliver dis note for me? I trust you not to open it, though I doubt you could read my scrawls anyway.", progress = "What is dis?", completion = "<B'wizati reads the note and wipes a tear from her eye.>\n\nHe may choose to forget, but I choose to remember, no matter what pain it brings me. \n\nAt least he is safe. Loa watch over him.", objectives = "Deliver Jorak's Note to B'wizati in Zuldazar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[49041] = { id = 49041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceFlavor = "retail", sourceRevision = "fb8e7e9117b5c99347d05ec8a30b0644fbef4fb8", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ruinhoof" }
